const fs = require("fs");
const file = "app/notes-cheat-sheets/commands-data.ts";
let source = fs.readFileSync(file, "utf8");

const start = source.indexOf('name: "Linux"');
if (start < 0) throw new Error("Linux tool not found");

const next = source.indexOf('name: "Bash"', start);
if (next < 0) throw new Error("Bash boundary not found");

const block = source.slice(start, next);
const commandsStart = block.indexOf("commands: [");
if (commandsStart < 0) throw new Error("Linux commands array not found");

const arrayStart = commandsStart + "commands: [".length;
let depth = 1, quote = false, escaped = false, arrayEnd = -1;

for (let i = arrayStart; i < block.length; i++) {
  const c = block[i];
  if (quote) {
    if (escaped) escaped = false;
    else if (c === "\\") escaped = true;
    else if (c === '"') quote = false;
    continue;
  }
  if (c === '"') quote = true;
  else if (c === "[") depth++;
  else if (c === "]" && --depth === 0) { arrayEnd = i; break; }
}
if (arrayEnd < 0) throw new Error("Could not locate Linux array end");

const existing = [...block.matchAll(/command:\s*"((?:\\.|[^"\\])*)"/g)]
  .map(m => m[1].replace(/\\"/g, '"').trim().toLowerCase());
const seen = new Set(existing);

